function validate([mat]) {
  if (!Array.isArray(mat) || mat.length < 1 || mat.length > 100) return 'mat needs 1 to 100 rows.';
  const n = mat[0].length;
  if (n < 1 || n > 100) return 'Each row needs 1 to 100 columns.';
  for (const line of mat) {
    if (line.length !== n) return 'All rows must have the same length.';
    if (line.some(v => v !== 0 && v !== 1)) return 'Every cell is 0 or 1.';
  }
  return null;
}

