function rowAndMaximumOnes(mat) {
  let bestRow = 0;
  let bestCount = -1;

  for (let row = 0; row < mat.length; row++) {
    let count = 0;
    for (let col = 0; col < mat[row].length; col++) {
      count += mat[row][col];
    }
    if (count > bestCount) {
      bestCount = count;
      bestRow = row;
    }
  }
  return [bestRow, bestCount];
}

