function generate(rand, size) {
  const m = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const style = Math.floor(rand() * 4);
  const density = style === 0 ? 0 : style === 1 ? 1 : rand();
  const mat = [];
  for (let i = 0; i < m; i++) {
    const rowDensity = style === 3 ? rand() : density;
    const line = [];
    for (let j = 0; j < n; j++) line.push(rand() < rowDensity ? 1 : 0);
    mat.push(line);
  }
  return [mat];
}
